        penAdd: 22 + tier * 3,
        critAdd: 10,
        aoe: (i % 2 === 0),
        targetSelector: 'MARKED_ENEMIES',
        comboFinisher: true,
        action: 'COMBO_FINISHER',
        domain: (i >= 9) ? DOMAIN_ROTATION[(pIdx + i) % DOMAIN_ROTATION.length] : undefined,
