      const w1 = pc.weapons[(i + 1) % pc.weapons.length];
      const w2 = pc.weapons[(i + 3) % pc.weapons.length];
      const tier = 3 + i;
      const noun = pc.themeNouns[(i + 8) % pc.themeNouns.length];

